import{y as o,b as t,c as n,X as r}from"./chunks/vue.Bn9cO5I3.js";import"./app.tjc9Wtrh.js";import"./chunks/mermaid.DvhSlOLG.js";const p=JSON.parse('{"title":"Thegent Orchestration Runbook (v1.0)","description":"","frontmatter":{},"headers":[],"relativePath":"RUNBOOK.md","filePath":"RUNBOOK.md","lastUpdated":1771753292000}'),i={name:"RUNBOOK.md"};function a(d,e,s,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="thegent-orchestration-runbook-v1-0" tabindex="-1">Thegent Orchestration Runbook (v1.0) <a class="header-anchor" href="#thegent-orchestration-runbook-v1-0" aria-label="Permalink to &quot;Thegent Orchestration Runbook (v1.0)&quot;">​</a></h1><p>(WP-6004: Runbook finalization and on-call readiness)</p><h2 id="_1-on-call-readiness" tabindex="-1">1. On-Call Readiness <a class="header-anchor" href="#_1-on-call-readiness" aria-label="Permalink to &quot;1. On-Call Readiness&quot;">​</a></h2><ul><li>undefined<strong>Cockpit Monitoring:</strong> Run <code>thegent cockpit</code> to check overall health.</li><li>undefined<strong>Failures:</strong> Check <code>thegent history --events</code> or <code>thegent benchmark</code> for failure patterns.</li><li>undefined<strong>Circuits:</strong> If a circuit is OPEN (red in cockpit), investigate the provider/agent. Circuits half-open automatically after 60s.</li><li>undefined<strong>MCP Verification:</strong> See <code>docs/VERIFICATION_RUNBOOK.md</code> for FastMCP server and tool checks.</li></ul><h2 id="_2-recovery-procedures" tabindex="-1">2. Recovery Procedures <a class="header-anchor" href="#_2-recovery-procedures" aria-label="Permalink to &quot;2. Recovery Procedures&quot;">​</a></h2><ul><li>undefined<strong>Stuck Tasks:</strong> Run <code>thegent dag reconcile</code> to fix tasks marked as <code>running</code> but whose processes are dead.</li><li>undefined<strong>Failed Tasks (Retry):</strong> Run <code>thegent dag recover --action retry-failed</code>.</li><li>undefined<strong>Failed Tasks (Fallback):</strong> Run <code>thegent dag recover --action fallback</code> to swap the agent to its defined backup.</li><li>undefined<strong>Corruption:</strong> Use <code>thegent history verify</code> to check if the run registry has been tampered with.</li><li>undefined<strong>Rollback:</strong> Use <code>thegent plan rollback</code> to restore from checkpoint.</li></ul><h2 id="_3-escalation" tabindex="-1">3. Escalation <a class="header-anchor" href="#_3-escalation" aria-label="Permalink to &quot;3. Escalation&quot;">​</a></h2><ul><li>undefined<strong>Feedback:</strong> <code>thegent govern feedback &lt;run_id&gt; &lt;score&gt; [note]</code> to record operator feedback.</li><li>undefined<strong>Health Gate:</strong> <code>thegent govern health-gate</code> for session contract health evaluation.</li><li>undefined<strong>Drift Alarms:</strong> <code>thegent govern conformance --check-drift</code> fails exit code when drift detected.</li><li>undefined<strong>Data Protection:</strong> <code>thegent govern data-protection</code> to audit WP-3006 controls (permissions, masking, retention).</li><li>undefined<strong>Override TTL (WP-3003):</strong> <code>--override</code> stores a policy override for <code>THGENT_OVERRIDE_TTL_SECONDS</code> (default 24h). Within TTL, subsequent runs auto-allow without re-supplying <code>--override</code>. After expiry, re-justify required.</li><li>undefined<strong>Escalation Queue (WP-3008):</strong> Policy-denied runs are added automatically. List with <code>thegent govern escalate list</code>; filter past-SLA with <code>--past-sla</code>. Resolve with <code>thegent govern escalate resolve &lt;run_id&gt;</code>.</li><li>undefined<strong>Policy Drift Sweep (WP-3005):</strong> <code>thegent govern sweep</code> runs drift detection, budget check, and past-SLA escalations. Cron-ready; exit 1 if issues found.</li></ul><h2 id="_4-post-launch-observation-wp-6007" tabindex="-1">4. Post-Launch Observation (WP-6007) <a class="header-anchor" href="#_4-post-launch-observation-wp-6007" aria-label="Permalink to &quot;4. Post-Launch Observation (WP-6007)&quot;">​</a></h2><p>See <code>docs/POST_LAUNCH_OBSERVATION_PLAYBOOK.md</code> for severity→SLA mapping and rollback checklist.</p><ul><li>undefined<strong>Daily:</strong> Run <code>thegent benchmark</code> and verify success rates are &gt; 90%.</li><li>undefined<strong>Contract Health:</strong> Monitor <code>thegent session-contract-health-report</code> for normalization quality.</li><li>undefined<strong>Drift Detection:</strong> Run <code>thegent observe drift</code> to identify degrading provider adapters.</li><li>undefined<strong>Drift Block (XC2):</strong> Use <code>thegent dag run --check-drift</code> to block DAG execution when drift detected.</li><li>undefined<strong>Weekly:</strong> Run <code>thegent archive</code> to prune old session data (tiered: THGENT_RETENTION_DAYS_SESSIONS).</li><li>undefined<strong>Audit:</strong> Generate a <code>thegent closure-pack</code> at the end of every major DAG session.</li><li>undefined<strong>Rollback Reserve:</strong> Before production cutover, ensure <code>thegent dag checkpoints</code> has a recent baseline; use <code>thegent dag rollback &lt;checkpoint_id&gt;</code> if needed.</li><li>undefined<strong>Trust Boundary (WP-3007):</strong> Skip-level promotions (dev→prod) require explicit audit; env transitions are validated.</li></ul><h2 id="_5-decommissioning-wp-6006" tabindex="-1">5. Decommissioning (WP-6006) <a class="header-anchor" href="#_5-decommissioning-wp-6006" aria-label="Permalink to &quot;5. Decommissioning (WP-6006)&quot;">​</a></h2><ul><li>undefined<strong>Sunset Plan:</strong> See <code>docs/enterprise/DECOMMISSIONING_PLAN.md</code> for target components and migration path.</li><li>undefined<strong>Legacy Commands:</strong> The <code>history-legacy</code> command is hidden and scheduled for sunset in v1.1.</li><li>undefined<strong>Temporary Sessions:</strong> All sessions in <code>.thegent/sessions</code> older than 30 days should be archived.</li></ul><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul>',16)])])}const k=o(i,[["render",a]]);export{p as __pageData,k as default};
